-- LOCAL ONLY: enrich the disposable pre-Phase-3 fixture after Phase 2.
BEGIN;
DO $$ BEGIN
    IF current_database() NOT LIKE 'vettrack_phase2_clinic_%' THEN
        RAISE EXCEPTION 'Clinic fixture requires a disposable vettrack_phase2_clinic_* database';
    END IF;
END; $$;
ALTER TABLE public.servicio RENAME COLUMN id TO id_servicio;
ALTER TABLE public.servicio
    ADD COLUMN nombre varchar(100) NOT NULL DEFAULT 'Legacy service',
    ADD COLUMN descripcion text,
    ADD COLUMN costo numeric(10,2) NOT NULL DEFAULT 0,
    ADD COLUMN id_veterinaria uuid REFERENCES public.veterinaria(id_veterinaria);
ALTER TABLE public.cita ADD CONSTRAINT cita_id_servicio_fkey
    FOREIGN KEY (id_servicio) REFERENCES public.servicio(id_servicio);

FROM unnest(ARRAY[
'20000000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000004',
'20000000-0000-4000-8000-000000000005','20000000-0000-4000-8000-000000000006',
'20000000-0000-4000-8000-000000000007','20000000-0000-4000-8000-000000000008',
'20000000-0000-4000-8000-000000000009']) AS ids(id);
'40000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001');
COMMIT;
